# fmt: on


# =========================================================================
# Lookup
# =========================================================================


def tr(key: str, lang: str = "en", module: str = "") -> str:
    """Look up an English key in *lang*'s table.

    With *module*, that module's own word comes first -- set in its
    ``i18n.json``, for that module only -- and TRCC's is used where it has
    none, by reference rather than a copy.  Without, only TRCC's table: no
    module's word ever reaches TRCC's own text.

    Falls back to English when *lang* is missing or the key isn't
    translated; falls back to the key itself if even English doesn't
    have it (the key *is* English — this only happens for unregistered
    strings, which are the bug to fix rather than the data to add).
    """
    log.debug("tr: key=%r lang=%s module=%s", key, lang, module)
    translated = (_MODULE_WORDS.get(module, {}).get(lang, {}).get(key)
                  or TRANSLATIONS.get(lang, {}).get(key))
    if translated:
        return translated
    english = TRANSLATIONS.get("en", {})
    return english.get(key, key)


#: Each module's own words, by module key then language -- kept apart from
#: ``TRANSLATIONS``, which is the app's own table and never changes at run
#: time, and apart from each other: one module's words never translate
#: another's text.
_MODULE_WORDS: dict[str, dict[str, dict[str, str]]] = {}


def add_translations(module: str, table: dict[str, dict[str, str]]) -> None:
    """Module *module*'s words (its ``i18n.json``, keyed like
    ``TRANSLATIONS``), in place of any it had -- so an update's words apply
    at once.  English is not added: an English key is its own text.  A
    language TRCC does not offer is skipped."""
    words = {lang: dict(entries) for lang, entries in table.items()
             if lang != "en" and lang in TRANSLATIONS and isinstance(entries, dict)}
    _MODULE_WORDS[module] = words
    log.info("add_translations: %s -- %d entr(ies) across %d language(s)", module,
             sum(len(w) for w in words.values()), len(words))


def drop_translations(module: str) -> None:
    """Module *module*'s words gone -- it was removed, or is being re-read."""
    gone = _MODULE_WORDS.pop(module, None)
    log.info("drop_translations: %s (%s)", module, "dropped" if gone else "none")


#: The panel's short weekdays, Monday first (``datetime.weekday()``'s order):
#: keys of ``TRANSLATIONS``, so a module uses them by reference.  Every
#: language's are from CLDR (``dev/tools/cldr_weekdays.py``).
WEEKDAY_KEYS = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN")


@functools.cache
def weekdays(lang: str) -> tuple[str, ...]:
    """*lang*'s seven short weekdays, Monday first -- the language itself,
    else its base subtag (``de_AT`` -> ``de``), else English.

    Cached: the render path asks once per frame and the answer changes only
    with the language, so the unknown-language WARNING fires once per
    language -- the line that explains English weekdays on a report."""
    base = lang.split("_", 1)[0]
    found = next((code for code in (lang, base) if code in TRANSLATIONS), "")
    if found:
        log.info("weekdays: %r -> %r", lang, found)
    else:
        log.warning("weekdays: %r is not a known language and its base subtag "
                    "%r isn't either -- weekdays fall back to English", lang, base)
    return tuple(tr(key, found or "en") for key in WEEKDAY_KEYS)


def supported_languages() -> list[str]:
    """ISO 639-1 codes for every language with at least one translation."""
    log.info("supported_languages: called")
    return sorted(TRANSLATIONS)


def language_name(lang: str) -> str:
    """Native-script name for a language code (e.g. 'zh' -> '简体中文').

    Returns the code itself when unknown so UIs never crash on a stale
    setting carried forward from an older release.
    """
    log.debug("language_name: lang=%s", lang)
    return LANGUAGE_NAMES.get(lang, lang)


# =========================================================================
# Locale / asset-suffix maps (single source of truth)
# =========================================================================


# System locale prefix → ISO 639-1 language code.  Used by anything that
# wants to derive the user's preferred UI language from
# ``locale.getlocale()[0]`` (e.g. ``"zh_CN.UTF-8"`` → ``"zh"``).
LOCALE_TO_LANG: dict[str, str] = {
    "zh_CN": "zh",
    "zh_TW": "zh_TW",
    "en":    "en",
    "de":    "de",
    "es":    "es",
    "fr":    "fr",
    "pt":    "pt",
    "ru":    "ru",
    "ja":    "ja",
    "ko":    "ko",
}


# Legacy C# asset suffix → ISO 639-1.  The Windows app shipped localized
# PNGs with single-letter suffixes (e.g. ``P0CZTVd.png`` = German).  Used
# by ``ui/gui/assets.py`` to translate ISO codes back into the suffix on
# disk when looking up localized assets.
LEGACY_TO_ISO: dict[str, str] = {
    "":   "zh",
    "tc": "zh_TW",
    "d":  "de",
    "e":  "ru",
    "f":  "fr",
    "p":  "pt",
    "r":  "ja",
    "x":  "es",
    "h":  "ko",
    "en": "en",
}
ISO_TO_LEGACY: dict[str, str] = {v: k for k, v in LEGACY_TO_ISO.items()}
